\section{Lemmata}\label{app:nlm}
\begin{lemma}\label{lem1}
    Let $\ket{\psi},\ket{\phi}$ two bipartite states with Schmidt spectrum $\lambda_i^2,\theta_j^2$. Then
    \begin{align}
        |\langle\psi|\phi\rangle|\le \sum_i{\lambda_i\theta_i}
    \end{align}
    with equality iff they are have the same Schmidt basis (ordered).
    \begin{proof}
        We can write every bipartite state as
        \begin{align}
            \ket{\psi}=\sum_{p,q}X_{pq}\ket{p}\ket{q}
        \end{align}
        where $\ket{p}$ (resp. $\ket{q}$) is a basis for $A$ (resp. $B$). Notoriously, the singular values of $X$ correspond to the Schmidt spectrum of $\ket{\psi}$. Hence, we have $X=U\lambda V^{\dagger}$ and $Y=R\theta W^{\dagger}$ with $Y$ the coefficient matrix corresponding to $\ket{\phi}$. We can write the overlap
        \begin{align}
            |\langle\psi|\phi\rangle|=|\tr(Y^{\dagger}X)|
        \end{align}
        and we need to show that $|\tr(Y^{\dagger}X)|\le \sum_{i}\lambda_i\theta_i$. First notice that
        \begin{align}
            \tr(Y^{\dagger}X)=\tr(\theta R^{\dagger}U\lambda V^{\dagger}W)
        \end{align}
        Defining $A=R^{\dagger}U$ and $B=V^{\dagger}W$, we have
        \begin{align}
            |\tr(Y^{\dagger}X)|=|\tr(\theta A\lambda B)|=\Big|\sum_{i,j}\theta_iA_{ij}\lambda_jB_{ji}\Big|\le \sum_{i,j}\theta_i\lambda_j |A_{ij}||B_{ji}|
        \end{align}
        Defining $C_{ij}=|A_{ij}||B_{ji}|$, let us show that $\sum_{i}C_{ij},\sum_{j}C_{ij}\le 1$. We have
        \begin{align}
            \sum_{j}C_{ij}=\sum_{j}|A_{ij}||B_{ji}|\le \Big(\sum_{j}|A_{ij}|^2\Big)^{1/2}\Big(\sum_{j}|B_{ji}|^2\Big)^{1/2}\le 1
        \end{align}
        where we used Cauchy-Schwartz inequality and the fact that both $A$ and $B$ are unitaries so:
        \begin{align}
            \sum_{j}|A_{ij}|^2=\sum_{j}A_{ij}A_{ij}^{*}=\sum_jA_{ij}(A^{\dagger})_{ji}=1
        \end{align}

    Now, we define $a_i=\lambda_i-\lambda_{i+1}$ and $b_i=\theta_i-\theta_{i+1}$ by identifying $\theta_{2^n+1}=0$. We can clearly write
    \begin{align}
        \lambda_i=\sum_{j\ge i}a_{j},\quad \theta_i=\sum_{j\ge i}b_j
    \end{align}
    implying
    \begin{align}
        \sum_{ij}\theta_i\lambda_j C_{ij}=\sum_{ij}\sum_{k\ge j}\sum_{l\ge i}C_{ij}a_{k}b_l=\sum_{i,j,k,l}C_{ij}a_kb_l\delta_{j\le k}\delta_{i\le l}=\sum_{kl}a_kb_l\sum_{i\le l,j\le k}C_{ij}
    \end{align}
    Now, notice that we can write
    \begin{align}
        \sum_{i\le l,j\le k}C_{ij}\le \sum_{i\le l}\sum_jC_{ij}\le l+1
    \end{align}
    and
    \begin{align}
        \sum_{i\le l,j\le k}C_{ij}\le \sum_{j\le k}\sum_iC_{ij}\le k+1
    \end{align}
    meaning that
    \begin{align}
        \sum_{ij}\theta_i\lambda_j C_{ij}\le \sum_{kl}a_kb_l\min\{k+1,l+1\}
    \end{align}
    On the other hand, we also have
    \begin{align}
        \sum_{i}\theta_i\lambda_i=\sum_{i,k,l}\delta_{i\le k}\delta_{i\le l}a_{k}b_l=\sum_{kl}a_kb_l\sum_{i}\delta_{i\le k}\delta_{i\le l}=\sum_{k,l}a_kb_l\min\{k+1,l+1\}
    \end{align}
    which proves the statement.
        \end{proof}
\end{lemma}

\begin{lemma}[Compression bound]\label{lem:compression}
Let $A\ge 0$ have eigenvalues $\lambda_1^\downarrow\ge\lambda_2^\downarrow\ge\dots$
and let $\Pi$ be a projector of rank $s$. Then
\begin{align}
\norm{A\Pi}_1\ \le\ \sum_{i=1}^{s}\lambda_i^\downarrow ,
\end{align}
with equality if and only if $\operatorname{supp}\Pi$ is a direct sum of
eigenspaces of $A$ exhausting its $s$ largest eigenvalues (with multiplicity).
\begin{proof}
$\norm{A\Pi}_1=\tr\sqrt{\Pi A^2\Pi}$. Let $\mu_1\ge\dots\ge\mu_s$ be the
eigenvalues of the compression $\Pi A^2\Pi|_{\operatorname{supp}\Pi}$. By Cauchy's
interlacing theorem $\mu_j\le(\lambda_j^\downarrow)^2$, hence
$\norm{A\Pi}_1=\sum_j\sqrt{\mu_j}\le\sum_{j\le s}\lambda_j^\downarrow$.
Equality forces $\mu_j=(\lambda_j^\downarrow)^2$ for every $j$, whence
$\tr(A^2\Pi)=\sum_{j\le s}(\lambda_j^\downarrow)^2$. This is the Ky Fan maximum of
$\tr(A^2\Pi)$ over rank-$s$ projectors, attained precisely when
$\operatorname{supp}\Pi$ is spanned by eigenvectors of $A^2$ belonging to its $s$
largest eigenvalues. Conversely, for such a $\Pi$ the compression is diagonal with
$\mu_j=(\lambda_j^\downarrow)^2$ and equality holds.
\end{proof}
\end{lemma}

