\begin{theorem}[Entanglement rerouting]\label{inf-thm:entanglement-rerouting}
Let $G=([n],E)$ be a graph, let $w:E\to\mathbb N$, and let
$|\psi\rangle\in\mathcal S_d(G,w)$. Choose an edge $e=\{x,y\}\in E$ and a
vertex $z\in[n]\setminus\{x,y\}$. Let
\begin{equation}
    E'=(E\setminus\{e\})\cup\{\{x,z\},\{y,z\}\},
\end{equation}
and extend $w$ by the convention $w(f)=1$ for $f\notin E$. Define
$w':E'\to\mathbb N$ by
\begin{equation}
    w'(f)
    =
    \begin{cases}
        w(f)w(e), & f\in\{\{x,z\},\{y,z\}\},\\
        w(f), & \text{otherwise}.
    \end{cases}
\end{equation}
Then, for $G'=([n],E')$,
\begin{equation}
    |\psi\rangle\in\mathcal S_d(G',w').
\end{equation}
Since $G'$ and $w'$ depend only on $G$, $w$, $e$, and $z$, the same
construction applies to every state in $\mathcal S_d(G,w)$; thus, $\mathcal S_d(G,w)
    \subseteq \mathcal S_d(G',w')$.
In particular, if every original edge dimension is at most $\chi$, then the
rerouted representation has maximum bond dimension at most $\chi^2$.
\end{theorem}

\Cref{inf-thm:entanglement-rerouting} (proved formally as \Cref{thm:entanglement-rerouting} below) shows that a virtual index can be routed through an intermediate vertex by enlarging the two edges on the new route.

\paragraph{Tensor network representations from graph parameters.}

Repeated applications of entanglement rerouting transform a TN on a general graph into one on a chosen target graph. This may increase the bond dimension. Our next two results bound this increase for paths and trees using cutwidth and tree-cutwidth.

\begin{theorem}[Transforming to MPS (informal)]\label{inf-thm:trafo-to-mps}
    A tensor network state on $n$ qudits with graph $G$, physical dimension $d$, and maximum bond dimension $\chi$ can be represented as an MPS on $n$ qudits with physical dimension $d$ and maximum bond dimension $\chi^{\cw(G)}$. Here, the cutwidth $\cw(G)$ is the smallest number $c$ such that the vertices of $G$ can be arranged on a line with at most $c$ edges crossing between any prefix of the arrangement and the rest. An ordering achieving the cutwidth can be computed in time $2^{O(\cw(G)^2)}n$.
\end{theorem}

\begin{theorem}[Transforming to TTN (informal)]\label{inf-thm:trafo-to-ttn}
    A tensor network state on $n$ qudits with graph $G$, physical dimension $d$, and maximum bond dimension $\chi$ can be represented as a TTN on at most $n$ grouped subsystems with physical dimension at most $d^{2\tcw(G)}$ and maximum bond dimension at most $\chi^{2\tcw(G)}$. Here, the tree-cutwidth $\tcw(G)$ is the analogue of cutwidth in which the vertices are organised into a tree of small groups rather than along a line. A tree-cut decomposition certifying these bounds can be computed in time $2^{O(\tcw(G)^2\log\tcw(G))}n^2$.
\end{theorem}

Every quantum state admits an MPS or TTN representation at sufficiently large bond dimension. \Cref{inf-thm:trafo-to-mps,inf-thm:trafo-to-ttn}, proved as \Cref{thm:reroute-to-mps,thm:reroute-to-ttn}, give explicit bounds on the bond dimension required when the starting point is a TN on a general weighted graph.

\paragraph{Learning tensor network states.}

We next use these representation results to study TNS tomography. Throughout, ``learning a state'' means performing tomography of that state, and we use the two terms interchangeably. Given a TNS on a complicated graph, we may first obtain a representation on a simpler graph and then apply a learner tailored to that representation.

We begin by proving efficient tomography of TTNs with known topology.

\begin{theorem}[TTN state tomography (informal)]\label{inf-thm:ttn-tomography}
    We can perform tomography of an unknown $n$-qudit TTN state with bond dimension $\chi$ (and with a known tree structure) from
    \begin{equation}
        O\left( \frac{n^{3}}{\varepsilon^{4}}\left( (d\chi)^{\max\{2,\Delta\}} + \log(n/\delta) \right)\right)
    \end{equation}
    many copies, where $\Delta=\Delta(T)$ is the maximum degree of the underlying tree $T$, $\varepsilon$ is the desired accuracy in trace norm, and $1-\delta$ is the desired success probability.
    The runtime of the tomography procedure is polynomial in $n$, $(d\chi)^{\max\{2,\Delta\}}$, $1/\varepsilon$, and $\log(1/\delta)$.
\end{theorem}

\Cref{inf-thm:ttn-tomography}, proved as \Cref{thm:ttn-tomography}, extends efficient MPS tomography~\cite{Cramer_2010,landoncardinal2010} to TTNs. For constant $d$ and $\chi$, the algorithm is both sample efficient and computationally efficient for TTNs of maximum degree $O(\log n)$. For paths, it recovers the known MPS bounds.

This gives two tractable target representations for learning, namely MPSs and TTNs. Combining the representation transformations with the corresponding tomography algorithms yields the following result for general TNSs:
\begin{theorem}[Parameterised complexity of black-box TNS tomography (informal)]\label{inf-thm:general-tns-learning-blackbox}
    We can perform tomography of an unknown TN state on $n$ qudits with (known) graph $G$, physical dimension $d$, and maximum bond dimension $\chi$ from
    \begin{equation}
        O\left( \frac{n^{3}}{\varepsilon^{4}}\left( \min\left\{ d^{2}\chi^{2\cw(G)},\ (d\chi)^{2\tcw(G)\max\{2,\Delta(\hat{\mathcal{T}})\}} \right\} + \log(n/\delta) \right)\right)
    \end{equation}
    many copies, where $\Delta(\hat{\mathcal{T}})$ is the maximum degree of the decomposition tree obtained from the computed tree-cut decomposition, $\varepsilon$ is the desired accuracy in trace norm, and $1-\delta$ is the desired success probability. The learner runs in time polynomial in $n$, the quantity inside the minimum, $1/\varepsilon$, and $\log(1/\delta)$, after computing an optimal cutwidth ordering in time $2^{O(\cw(G)^2)}n$ or an approximate tree-cut decomposition in time $2^{O(\tcw(G)^2\log\tcw(G))}n^2$.
\end{theorem}

The proof of \Cref{inf-thm:general-tns-learning-blackbox}, given in \Cref{thm:blackbox-mps-learning,thm:blackbox-tcw-learning}, first uses cutwidth or tree-cutwidth to obtain a structured representation and then applies the corresponding tomography algorithm. The graph parameters bound the increase in bond dimension and thereby the overall learning complexity.

The approach to general-graph TNS tomography in \Cref{inf-thm:general-tns-learning-blackbox} uses the transformations of \Cref{inf-thm:trafo-to-mps,inf-thm:trafo-to-ttn} as black boxes (see also the discussion in \Cref{subsec:technical-overview} below).
The preceding construction is modular, but treating the representation transformations as black boxes can yield weaker bounds. Our next result works directly with cuts of the original graph along a chosen sequence of subsets, and its cost is described by a finer graph parameter.

\begin{theorem}[Parameterised complexity of direct TNS tomography (informal)]\label{inf-thm:general-tns-learning-white-box}
    We can perform tomography of an unknown TNS on $n$ qudits with (known) graph $G$, physical dimension $d$, and maximum bond dimension $\chi$ from
    \begin{equation}
        O\left( \frac{n^{3}}{\varepsilon^{4}}\left( d^{\,\lc_{d,\chi}(G)} + \log(n/\delta) \right)\right)
    \end{equation}
    many copies, where $\varepsilon$ is the desired accuracy in trace norm, and $1-\delta$ is the desired success probability.
Here, $\lc_{d,\chi}(G)$ is a graph parameter that we call \emph{learning complexity}. It is the minimum over learning sequences of the largest combined size of an active subsystem and its retained residual register. We show that
    \begin{equation}
        \lc_{d,\chi}(G)
        \leq
        \min\left\{
            n,
            3\max\{1,\lceil \CC(G)\log_d\chi\rceil\}
        \right\}.
    \end{equation}
    In particular,
    $\lc_{d,\chi}(G)=O\left(\Delta\,\tw(G)\max\{1,\lceil\log_d\chi\rceil\}\right)$
    when $G$ is connected and has at least two vertices. Here, $\CC(G)$ is the contraction complexity of Markov and Shi \cite{Markov_2008}, $\Delta=\Delta(G)$ is the maximum degree of $G$, and the treewidth $\tw(G)$ measures how well the vertices of $G$ can be organised into a tree of small overlapping bags.
    The learner runs in time polynomial in $n$, $d^{\,\lc_{d,\chi}(G)}$, $1/\varepsilon$, and $\log(1/\delta)$ once a learning sequence achieving the bound is supplied.  A learning sequence attaining the upper bound can be constructed from an optimal contraction sequence in time $2^{O(\CC(G)^2)}\poly(n)$.
\end{theorem}

The formal version of \Cref{inf-thm:general-tns-learning-white-box} is
\Cref{thm:learning-sequence-tomography}, while \Cref{cor:lc-upper-bound} gives
the displayed estimate in terms of contraction complexity. The direct approach
does not choose an MPS or TTN target in advance. Its exponent depends on the cuts
encountered along the chosen learning sequence.

The precise learning-sequence bound contains the path and tree schedules used by
the black-box algorithms as special cases. Optimising over learning sequences can
only improve on these choices. The contraction-complexity estimate is a more general
bound obtained from a particular learning sequence and can be less sharp on some
graph families.

Finally, we extend the direct approach to agnostic tomography. The input may
lie outside $\mathcal S_d(G,\chi)$, and the algorithm outputs a pure state whose
fidelity is within additive error $\epsilon$ of the optimum over that class.
The output is represented by the circuit produced by the algorithm and need not lie in $\mathcal S_d(G,\chi)$. That is, it need not admit a
representation on $G$ with bond dimension at most $\chi$.

\begin{theorem}[Agnostic TNS tomography (informal)]
\label{inf-thm:agnostic-tns-tomography}
Let $\rho$ be an arbitrary $n$-qudit state, and let a graph $G$, a bond dimension bound $\chi$, and a learning sequence for $G$ be known. Suppose further that
\begin{equation}
    \operatorname{OPT}_{G,\chi}(\rho)
    :=
    \sup_{|\phi\rangle\in\mathcal S_d(G,\chi)}
    \langle\phi|\rho|\phi\rangle
    \geq
    \vartheta
\end{equation}
for a known $\vartheta>0$.
There is an algorithm that outputs a pure state $|\hat\psi\rangle$ such that
\begin{equation}
    \langle\hat\psi|\rho|\hat\psi\rangle
    \geq
    \operatorname{OPT}_{G,\chi}(\rho)-\epsilon
\end{equation}
with probability at least $1-\delta$. Its copy and computational complexity are polynomial in the length of the learning sequence, $1/\vartheta$, $1/\min\{\epsilon,\vartheta\}$, and $\log(1/\delta)$, and exponential only in the largest active register induced by the sequence.
\end{theorem}

The formal statement of \Cref{inf-thm:agnostic-tns-tomography} and its specialisations to contraction sequences and TTNs are given in \Cref{thm:agnostic-learning-sequence-tomography,cor:agnostic-contraction-complexity,cor:agnostic-ttn-tomography}.

\subsection{Technical overview}\label{subsec:technical-overview}

\paragraph{Entanglement rerouting.}
Suppose that an edge $e=\{x,y\}$ in a TNS with weighted graph $(G,w)$ is to be rerouted through a vertex $z\neq x,y$, as shown in \Cref{fig:rerouting-tns}. Multiply the dimensions of $\{x,z\}$ and $\{y,z\}$ by $w(e)$ and delete $e$. View the two enlarged indices as pairs $(i,j)$ and $(k,\ell)$, where $j,\ell\in[w(e)]$. The new tensor at $z$ retains the old tensor entries when $j=\ell$ and is zero otherwise. This enforces equality of the two components carrying the rerouted index, so summing over the enlarged indices reproduces the original contraction.

