\paragraph{Treewidth and contraction complexity.}
Treewidth measures how closely a graph resembles a tree. Its definition uses a tree decomposition, which partitions the vertices into overlapping bags indexed by a tree.
We use $\mathcal T$ for a decomposition tree whose vertices index bags, and $T$ for a tree that is itself used as a tensor-network graph.

\begin{definition}[Tree decomposition {\cite{RobertsonSymour1986}}]
    A {\em tree decomposition} of a graph $G=(V,E)$ is a tree $\mathcal{T}$, together with a mapping $t\mapsto B_t$ from vertices $t\in V(\mathcal{T})$ to subsets $B_t \subseteq V(G)$, called bags, such that the following conditions hold:
    \begin{itemize}
        \item $\bigcup_{t\in V(\mathcal{T})} B_t = V(G)$, that is, each vertex appears in at least one bag.
        \item For every edge $\{u,v\}\in E(G)$, there is a vertex $t\in V(\mathcal{T})$ such that $\{u,v\}\subseteq B_t$, that is, at least one bag contains both endpoints of every edge.
        \item For every $u\in V(G)$, the set $\{t\in V(\mathcal{T})~|~u\in B_t\}$ forms a connected subtree of $\mathcal{T}$.
    \end{itemize}
    The {\em width} of a tree decomposition is $\max_{t\in V(\mathcal{T})}|B_t|-1$. The {\em treewidth} of $G$ is the minimum width over all tree decompositions,
    \begin{equation}
        \tw(G)
        =
        \min_{\mathcal{T}}
        \left(
            \max_{t\in V(\mathcal{T})}|B_t|-1
        \right).
    \end{equation}
\end{definition}
Finding an optimal tree decomposition of $G$ can be done in time $2^{O(\tw^2)}n^{O(1)}$, as shown in \cite{korhonen2023improvedparameterizedalgorithmtreewidth}.

\begin{example}
    We now illustrate this definition with some simple examples (see \Cref{fig:example-graphs}):
    \begin{enumerate}
        \item The treewidth of a tree with at least two vertices is equal to $1$, independently of its size. In particular, the treewidth of the star is $1$.

        \item The treewidth of the clique $K_n$ is $n-1$.

        \item The treewidth of a square lattice with $n^2$ vertices is $n$. Note that such a graph is the entanglement graph of a Projected Entangled Pair State (PEPS). 
    \end{enumerate}
\end{example}

We next introduce contraction complexity, a graph parameter used to analyse the cost of tensor network contraction~\cite{Markov_2008}. It is closely related to treewidth.

\begin{definition}[Contraction complexity {\cite[Definition 4.1]{Markov_2008}}]\label{def:contraction-complexity}
    A contraction sequence starts from $G$ and repeatedly chooses a non-loop edge of the current multigraph and identifies its endpoints, until every connected component of $G$ has been contracted to a single vertex. Parallel edges are retained and counted with multiplicity, while loops created by an identification are deleted. The complexity of the sequence is the maximum degree, counted with multiplicity, of any vertex created by a contraction. Thus the degrees of the initial vertices are not included unless a vertex later appears as the result of a contraction. The {\em contraction complexity} of $G$, denoted by $\cc(G)$, is the minimum of this quantity over all contraction sequences. If no contraction is required, we set $\cc(G)=0$.
\end{definition}

We can bound $\cc(G)$ using maximum degree and treewidth.

\begin{theorem}[Bounds on contraction complexity {\cite[Theorem 4.5]{Markov_2008}}] \label{thm:cc-vs-tw-delta}
    For any graph $G$ with maximum degree $\Delta=\Delta(G)$, we have 
    \begin{equation}
        (\tw(G)-1)/2\le \cc(G) \le \Delta(\tw(G)+1)-1\, .
    \end{equation}
\end{theorem}
Markov and Shi also prove the exact identity $\cc(G)=\tw(L(G))$ and show how to construct a contraction sequence of the same width from a tree decomposition of $L(G)$~\cite{Markov_2008}. Combined with the exact treewidth algorithm of \cite{korhonen2023improvedparameterizedalgorithmtreewidth}, this gives an optimal contraction sequence in time $2^{O(\cc(G)^2)}|E|^{O(1)}$.

\paragraph{Cutwidth and tree-cutwidth.}
Cutwidth~\cite{doi:10.1137/0606026} is the minimum, over linear orderings of the vertices, of the largest edge cut between a prefix and the remaining vertices.

\begin{definition}[Cutwidth]
    The cutwidth of a bijection $\pi:V\rightarrow [n]$ is defined as 
    \begin{equation}
        \cw(\pi)=\max_{i\in[n]} |\cut(\{v\in V~|~\pi(v)\leq i\})|.
    \end{equation}
    The cutwidth of $G=(V,E)$ is defined as $\cw(G) = \min_{\pi} \cw(\pi)$.
\end{definition}
We often call $\pi$ a linear ordering. 
Finding an optimal ordering can be done in time $2^{O(\cw^2)}n$, as shown in \cite{THILIKOS20051, THILIKOS200525}.

Tree-cutwidth~\cite{wollan2015structure} is a tree-structured analogue of cutwidth. Its definition uses a near partition.

\begin{definition}
A \emph{near partition} of $X$ is a pairwise disjoint family $X_1,\ldots,X_k\subseteq X$ whose union is $X$, allowing for the possibility of $X_i$ to be empty.
\end{definition}

We next define a tree-cut decomposition of a graph $G$.

\begin{definition}[Tree-cut decomposition]
    A \emph{tree-cut decomposition} of $G$ is a pair $(\mathcal{T},\mathcal{X})$ where $\mathcal{T}$ is a rooted tree, with root $r$, and $\mathcal{X} = \{X_t \subseteq V(G): t\in V(\mathcal{T})\}$ is a near partition of $V(G)$. The sets $X_t$ are called bags.
\end{definition}

Tree-cutwidth is now defined using two terms, adhesion and torso size. These in turn are defined with respect to a tree-cut decomposition $(\mathcal{T},\mathcal{X})$.

\begin{definition}[Adhesion]
Let $(\mathcal T,\mathcal X)$ be a tree-cut decomposition of $G$. Let $t\neq r$ have parent $u$, and let $e=\{u,t\}$. Deleting $e$ separates $\mathcal T$ into components $\mathcal T_u$ and $\mathcal T_t$ containing $u$ and $t$, respectively. The \emph{adhesion} $\adh(t)$ is the number of edges of $G$ joining vertices in bags on opposite sides of this separation:
    \begin{equation}
        \adh(t) = \left|\cut\left(\bigcup_{b\in V(T_u)} X_b,\bigcup_{b\in V(T_t)} X_b \right)\right| \, .
    \end{equation}
    For the root $r$, which has no parent, we set $\adh(r)=0$.
\end{definition}

\begin{definition}[Torso size]
\label{def:torso-size}
Let $(\mathcal{T},\mathcal X)$ be a tree-cut decomposition of a graph $G$, where
$\mathcal X=\{X_t:t\in V(\mathcal{T})\}$. Fix $t\in V(\mathcal{T})$, and let
$T_1,\ldots,T_\ell$ be the connected components of $\mathcal{T}-t$.

The torso of $(\mathcal{T},\mathcal X)$ at $t$, denoted $H_t$, is the multigraph obtained from
$G$ as follows: For every $i\in[\ell]$, contract the vertex set
\begin{equation}
    \bigcup_{s\in V(T_i)} X_s
\end{equation}
to a single vertex $z_i$, preserving parallel edges and deleting loops. The vertices in
$X_t$ are called the core vertices of $H_t$, and the vertices
$z_1,\ldots,z_\ell$ are called the peripheral vertices of $H_t$.

The $3$-centre of $H_t$, denoted $\widetilde H_t$, is obtained from $H_t$ by repeatedly
suppressing peripheral vertices of degree at most $2$, while never suppressing core
vertices. More precisely, while there exists a peripheral vertex $z\notin X_t$ with
$\deg(z)\leq 2$, perform one of the following operations:
\begin{itemize}
    \item If $\deg(z)=0$ or $\deg(z)=1$, delete $z$ and all edges incident to $z$.
    \item If $\deg(z)=2$, with incident neighbours $a$ and $b$, delete $z$ and its
    incident edges and, if $a\neq b$, add an edge $\{a,b\}$, preserving multiplicity.
\end{itemize}
The torso size of $t$ is
\begin{equation}
    \operatorname{tor}(t)=|V(\widetilde H_t)|.
\end{equation}
\end{definition}

The tree-cutwidth is then defined as follows:

\begin{definition}[Tree-cutwidth]
    Let $(\mathcal{T},\mathcal{X})$ be a tree-cut decomposition of $G$. The \emph{width} of such a tree-cut decomposition is $\max_{t\in V(\mathcal{T})}\{\adh(t),\tor(t)\}$. 
    The \emph{tree-cutwidth} of $G$, denoted $\tcw(G)$, is the minimum width of all tree-cut decompositions of $G$.
\end{definition}
A tree-cut decomposition of $G$ of width at most $2\tcw(G)$ can be computed in time $2^{O(\tcw^2\log\tcw)}n^2$, as shown in \cite{Kim2018}. 

\begin{remark}
\label{rem:torso-size-bounds-bag-size}
The vertices in the central bag $X_t$ are never suppressed when forming the $3$-centre $\widetilde H_t$, so$|X_t|\leq \operatorname{tor}(t)$ for every $t\in V(\mathcal T)$. In particular, every bag in a width-$k$ tree-cut decomposition has size at most $k$.
\end{remark}

